import Testing
import DartCore
import DartGames
import DartTestSupport

/// Cross-check of Around the Clock against the Python reference that computed the vectors of GAMES.md: 50 random
/// journals, 1 to 8 players, every combination of `finishOnBull` and `multiplierJump`, with and without a round
/// limit. The reference recorded a hash of the state after every input (progress, target, darts thrown, ranks,
/// phase, current player, round) and the final state; 18 games end on a victory.
@Suite struct AroundTheClockOracleTests {
    private let registry = GameRegistry.standard

    /// "T-|1|8|1|15,16,24/14,15,22|1.2": turn state, one row "progress,target,dartsThrown" per player, ranks.
    private func state(_ match: GameMatch) -> String {
        let rows = match.snapshot.players.map { row -> String in
            ["progress", "target", "dartsThrown"].map { name -> String in
                if case .int(let value)? = row.facts[name] { return String(value) }
                return "?"
            }.joined(separator: ",")
        }
        return "\(KillerTestOracle.turnState(match))|\(rows.joined(separator: "/"))|\(KillerTestOracle.ranks(match))"
    }

    @Test func referenceJournals_sameStateAfterEveryInput() throws {
        let lines = Self.journals.split(separator: "\n")
        #expect(lines.count == 50)
        var victories = 0
        for (index, line) in lines.enumerated() {
            let fields = line.split(separator: ";", omittingEmptySubsequences: false).map(String.init)
            try #require(fields.count == 7, "line \(index)")
            let options: GameOptions = [
                "finishOnBull": .bool(fields[1] == "1"),
                "multiplierJump": .bool(fields[2] == "1"),
                "maxRounds": fields[3] == "-" ? .null : .int(try #require(Int(fields[3]))),
            ]
            var match = try registry.match(.aroundTheClock, options, players: try #require(Int(fields[0])))
            var states = KillerTestOracle.emptyHash
            for input in try KillerTestOracle.inputs(fields[4]) {
                let outcome: InputOutcome
                switch input {
                case .dart(let hit): outcome = match.throwDart(DartRecord(hit: hit))
                case .endTurn: outcome = match.endTurn()
                }
                #expect(outcome.isAccepted, "line \(index): the reference only recorded accepted inputs")
                KillerTestOracle.mix(&states, state(match) + ";")
            }
            #expect(state(match) == fields[6], "line \(index): final state")
            #expect(String(states, radix: 16) == fields[5].drop { $0 == "0" }, "line \(index): a state differs on the way")
            if match.snapshot.finishReason == .victory { victories += 1 }
        }
        #expect(victories == 18)
    }

